import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"RFC-031 — Keyboard-first navigation, focus model & WCAG 2.1 AA elevation (a11y Tier 2 · Google TV)","description":"","frontmatter":{},"headers":[],"relativePath":"rfc/RFC-031.md","filePath":"rfc/RFC-031.md"}'),n={name:"rfc/RFC-031.md"};function s(i,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="rfc-031-—-keyboard-first-navigation-focus-model-wcag-2-1-aa-elevation-a11y-tier-2-·-google-tv" tabindex="-1">RFC-031 — Keyboard-first navigation, focus model &amp; WCAG 2.1 AA elevation (a11y Tier 2 · Google TV) <a class="header-anchor" href="#rfc-031-—-keyboard-first-navigation-focus-model-wcag-2-1-aa-elevation-a11y-tier-2-·-google-tv" aria-label="Permalink to &quot;RFC-031 — Keyboard-first navigation, focus model &amp; WCAG 2.1 AA elevation (a11y Tier 2 · Google TV)&quot;">​</a></h1><blockquote><p>Status · Draft Date · 2026-07-09 Gates · #375 (TV + a11y epic) · <strong>extends ADR-025</strong> (accessibility Tier-1 contract → executes its deferred Tier 2) · mobile epic #149 · Google-TV target (RFC-030) Closes-toward · ADR-025 Tier 2 (&quot;canvas object keyboard navigation&quot;, &quot;full screen-reader description of canvas content&quot;, formal WCAG target) ADR · to follow (locks the interaction contract + conformance target once slices settle)</p></blockquote><blockquote><p><strong>Why this is an RFC.</strong> ADR-025 shipped an honest a11y Tier 1 and explicitly deferred <em>canvas object keyboard navigation</em> to &quot;v2&quot;, calling it an architecture change (a parallel DOM mirror or an SVG migration). Two things have since changed: (1) the parallel DOM mirror already exists as a substrate (<code>select {planetId}</code> / <code>select {moduleId}</code> buttons on <code>/explore</code> · <code>/iss</code> · <code>/tiangong</code>, built for pickability + e2e per ADR-056), and (2) Google TV (RFC-030 target, #375) needs a <strong>D-pad remote</strong>, which is the same input model as a keyboard. So the deferred a11y work and the TV work are one build. This RFC locks the interaction contract, the focus architecture, the TV layer, and the WCAG 2.1 AA target across every route + 3D scene before the slices, so they don&#39;t re-litigate the focus model page-by-page (the exact fragmentation ADR-025 was written to stop).</p></blockquote><p><strong>Gating sentence</strong>: every interactive affordance in Orrery — including objects inside a 3D/2D canvas — is reachable and operable with <strong>keyboard alone</strong>, via one shared roving/spatial-focus engine that drives an elevated <strong>parallel DOM mirror</strong> (a focusable, correctly-ordered, <code>:focus-visible</code> button per canvas object whose focus <strong>highlights the object in-scene, announces it to a screen reader, and optionally eases the camera to it</strong>); the <strong>same engine is the Google-TV D-pad experience</strong> under a 10-foot / overscan-safe TV layer; a <strong>global command palette</strong> (<code>Cmd-K</code>, promoted app-wide) is the jump-to-anything escape hatch on all three surfaces; and the whole app is brought to a <strong>formally audited WCAG 2.1 AA</strong> conformance target with a published accessibility statement. A TV remote is a keyboard (←→↑↓ + Enter/Back) — we build the keyboard once and get the remote for free.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><ul><li><strong>ADR-025 Tier 1 (shipped):</strong> reduced-motion, nav keyboard activation, global <code>:focus-visible</code>, panel focus move/return + Esc, WAI-ARIA tab strips, radiogroup filter pills, honest canvas <code>aria-label</code>s, <code>aria-live</code> status/alert regions, 44 px targets. Strong foundation — 63 files already use <code>:focus-visible</code>.</li><li><strong>ADR-025 Tier 2 (deferred, this RFC):</strong> tabbing between objects <em>within</em> a canvas; full screen-reader canvas description; a formal WCAG target. (High-contrast, also listed Tier 2, has since shipped as a toggle.)</li><li><strong>The substrate exists:</strong> <code>/explore</code> renders one hidden <code>&lt;button&gt;</code> per planet/body; <code>/iss</code> + <code>/tiangong</code> render one per module. Today they are click/e2e/SR hooks, not a <em>navigation experience</em> — no coherent focus order, no focus→highlight, no camera coupling, no D-pad camera control, not TV-scaled.</li><li><strong>Google TV (RFC-030 / #375):</strong> a Capacitor Android build on a <strong>D-pad remote</strong> with no touchscreen. Same directional-focus model as a keyboard; adds only a 10-foot presentation layer.</li></ul><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ol><li><strong>Keyboard-complete</strong>: 100% of interactive affordances operable by keyboard, including canvas objects (WCAG 2.1.1, no traps 2.1.2).</li><li><strong>One focus engine</strong> shared by lists, panels, and canvas scenes — no per-page reinvention.</li><li><strong>Screen-reader canvas access</strong>: focusing a canvas object announces it (name + key datum).</li><li><strong>Google-TV usable on a remote</strong> under a 10-foot/overscan layer, driven by the same engine.</li><li><strong>Command palette</strong> app-wide as the jump-to-anything surface (keyboard + remote + power users).</li><li><strong>WCAG 2.1 AA</strong> formally audited + a published accessibility statement.</li></ol><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><ul><li><strong>Apple TV / tvOS</strong> — no WKWebView on tvOS; architecturally out (per #375, would be a native rewrite / separate PRD).</li><li><strong>SVG re-render of the 3D scenes</strong> — the DOM-mirror approach makes it unnecessary (ADR-025&#39;s other option, explicitly not taken).</li><li><strong>AAA conformance</strong> — AA is the target; AAA items adopted only where free.</li><li><strong>Voice / switch-access hardware</strong> — future, not this RFC.</li></ul><h2 id="the-model-—-one-input-abstraction-three-surfaces" tabindex="-1">The model — one input abstraction, three surfaces <a class="header-anchor" href="#the-model-—-one-input-abstraction-three-surfaces" aria-label="Permalink to &quot;The model — one input abstraction, three surfaces&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌──────────────── shared roving / spatial-focus engine ────────────────┐</span></span>
<span class="line"><span>        │  focus order · directional (2D) move · activate · escape · announce   │</span></span>
<span class="line"><span>        └───────────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>             ▲                         ▲                              ▲</span></span>
<span class="line"><span>      desktop keyboard          screen reader                   TV D-pad remote</span></span>
<span class="line"><span>      (Tab / arrows / Enter)    (focus + aria-live)             (←→↑↓ / OK / Back)</span></span>
<span class="line"><span>                                                                + 10-foot layer</span></span></code></pre></div><p>A TV remote emits the same events as a keyboard. We implement the keyboard model correctly; the remote and the screen reader are the same model observed on different surfaces. The only TV-specific work is <em>presentation</em> (size, spacing, overscan, focus-ring weight), never <em>interaction</em>.</p><h2 id="design-decisions" tabindex="-1">Design decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design decisions&quot;">​</a></h2><p><strong>D1 — Shared spatial-focus primitive.</strong> A Svelte-5 store (<code>src/lib/a11y/roving-focus.svelte.ts</code>): register focusable items with an ordering + optional 2D screen position; expose roving tabindex, directional move (<code>up/down/left/right</code> → nearest item by geometry for canvas, by order for lists), <code>activate</code>, and <code>escape</code>. Every list and every canvas mirror consumes it. This replaces the ad-hoc per-page focus code ADR-025 warned was fragmenting.</p><p><strong>D2 — Elevate the parallel DOM mirror.</strong> Keep the existing per-object <code>&lt;button&gt;</code>s; make them (a) ordered + roving-tabindex, (b) <code>:focus-visible</code>-ringed, (c) positioned over the object&#39;s screen projection (reuse the ADR-056 project-to-client math), (d) on focus → highlight the object in-scene + <code>aria-live</code> announce + optional camera ease-to. Complete the mirror where missing: surfaces <code>/moon</code> <code>/mars</code> <code>/earth</code>, and <code>/fly</code>.</p><p><strong>D3 — Camera on keys/D-pad.</strong> Two interaction intents share the remote/keyboard: <em>traverse objects</em> (default — arrows move focus between mirror buttons) and <em>fly the camera</em> (arrows orbit/zoom). Resolve via an explicit mode toggle (e.g. OK-on-empty or a dedicated key) documented per scene; never trap the user in camera mode (Back/Tab always escapes).</p><p><strong>D4 — Global command palette.</strong> Promote the <code>/science</code> <code>Cmd-K</code> into an app-wide palette (<code>src/lib/components/CommandPalette.svelte</code>): fuzzy index of routes + planets + bodies + missions + fleet + station modules. Keyboard <code>Cmd/Ctrl-K</code>; a visible entry point for TV (a &quot;Search&quot; affordance in nav). This is the jump-to-anything escape hatch that makes 100-item lists bearable on a remote and instant for keyboard users.</p><p><strong>D5 — TV / 10-foot layer.</strong> Detect the 10-foot context (<code>(hover: none) and (pointer: coarse)</code> + large viewport, and/or a <code>__TV__</code>/leanback build signal) and apply a presentation layer: larger type scale, increased spacing, <strong>overscan-safe margins (~5%)</strong>, heavier focus rings (3–4 px), and removal of hover-only affordances (tooltips become focus-driven). Presentation only — no separate interaction code path.</p><p><strong>D6 — Screen-reader canvas narration.</strong> When a mirror button gains focus, an <code>aria-live=&quot;polite&quot;</code> region announces the object (name + one key datum, e.g. &quot;Mars — 4th planet&quot; / &quot;Zarya — first ISS module, 1998&quot;). Turns an opaque canvas into a navigable list for SR users — ADR-025&#39;s deferred &quot;full description&quot;, done incrementally and without flooding (announce on focus, not on every frame).</p><p><strong>D7 — WCAG 2.1 AA conformance target.</strong> Formal audit (axe-core automated + manual keyboard/SR/contrast pass), a tracked fix list, and a <strong>published accessibility statement</strong> (<code>/accessibility</code> route or <code>docs/</code>), stating conformance level + known limitations. High-contrast toggle already covers a chunk of the contrast criteria.</p><p><strong>D8 — Testing on both surfaces.</strong> Playwright <strong>keyboard-only</strong> journeys on <code>desktop-chromium</code> (Tab/arrow/Enter reaches every affordance incl. canvas objects) + a <strong>TV surface</strong> (emulated 1080p + <code>hover:none</code>, or the <code>Orrery_TV</code> emulator for manual). <code>axe-core</code> per-route checks wired into e2e as a gate. Same assertions, two surfaces.</p><h2 id="key-mappings-contract" tabindex="-1">Key mappings (contract) <a class="header-anchor" href="#key-mappings-contract" aria-label="Permalink to &quot;Key mappings (contract)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Input</th><th>Keyboard</th><th>TV remote</th><th>Action</th></tr></thead><tbody><tr><td>Move focus (list)</td><td>Tab / Shift-Tab, ↑↓</td><td>D-pad ↑↓</td><td>roving focus, next/prev</td></tr><tr><td>Move focus (canvas)</td><td>↑↓←→</td><td>D-pad ↑↓←→</td><td>nearest object by geometry</td></tr><tr><td>Activate</td><td>Enter / Space</td><td>OK</td><td>open panel / select object</td></tr><tr><td>Dismiss</td><td>Esc</td><td>Back</td><td>close panel / exit mode</td></tr><tr><td>Camera mode</td><td>(per-scene key)</td><td>(per-scene)</td><td>arrows orbit/zoom</td></tr><tr><td>Command palette</td><td>Cmd/Ctrl-K</td><td>&quot;Search&quot; affordance</td><td>jump-to-anything</td></tr></tbody></table><h2 id="slices-each-→-a-sub-issue-under-375" tabindex="-1">Slices (each → a sub-issue under #375) <a class="header-anchor" href="#slices-each-→-a-sub-issue-under-375" aria-label="Permalink to &quot;Slices (each → a sub-issue under #375)&quot;">​</a></h2><ul><li><strong>S0 · Audit + baseline.</strong> axe-core wired into e2e; contrast/token pass; focus-order map per route; add a skip-link; findings + fix list doc in <code>docs/wip/</code>.</li><li><strong>S1 · Spatial-focus primitive</strong> (<code>roving-focus.svelte.ts</code>) + convert the big lists (nav, <code>/missions</code>, <code>/fleet</code>, station module lists, <code>/science</code>) to it. No canvas yet.</li><li><strong>S2 · Elevate the <code>/explore</code> mirror</strong> — order, focus-visible, focus→highlight + SR announce + camera-ease for planets/bodies.</li><li><strong>S3 · Elevate <code>/iss</code> + <code>/tiangong</code> mirrors</strong>, then complete the mirror on <code>/moon</code> <code>/mars</code> <code>/earth</code> + <code>/fly</code>.</li><li><strong>S4 · Camera keyboard/D-pad control</strong> across all scenes (mode contract from D3). <strong>DEFERRED — future work.</strong> Content is fully reachable without it via the per-scene DOM object indexes (S2/S3); only camera <em>manipulation</em> (orbit/pan/zoom) stays pointer-driven, which is not required for WCAG 2.1 AA reachability. Tracked for a later pass — see <code>docs/accessibility.md</code> §Known limitations.</li><li><strong>S5 · Global command palette</strong> (promote <code>Cmd-K</code> app-wide).</li><li><strong>S6 · TV 10-foot layer</strong> — detection, type scale, overscan, focus-ring weight, hover→focus tooltips. (Leanback manifest + banner already shipped, <code>fd1ea15adc</code>.)</li><li><strong>S7 · Accessibility statement</strong> page + WCAG 2.1 AA conformance claim + <code>docs/</code> update; close ADR-025 Tier 2 in a follow-up ADR.</li><li><strong>S8 · Keyboard + TV e2e</strong> journeys + axe gate in CI.</li></ul><h2 id="wcag-2-1-aa-success-criteria-touched" tabindex="-1">WCAG 2.1 AA success criteria touched <a class="header-anchor" href="#wcag-2-1-aa-success-criteria-touched" aria-label="Permalink to &quot;WCAG 2.1 AA success criteria touched&quot;">​</a></h2><p>2.1.1 Keyboard · 2.1.2 No keyboard trap · 2.4.3 Focus order · 2.4.7 Focus visible · 2.1.4 Character-key shortcuts (palette) · 1.4.3 Contrast (audit + high-contrast) · 2.5.5 Target size (Tier 1: 44 px, re-verify) · 2.3.3 Animation from interactions (reduced-motion, shipped) · 4.1.2 Name/role/value (mirror buttons) · 4.1.3 Status messages (narration live regions).</p><h2 id="risks-open-questions" tabindex="-1">Risks / open questions <a class="header-anchor" href="#risks-open-questions" aria-label="Permalink to &quot;Risks / open questions&quot;">​</a></h2><ul><li><strong>Camera-vs-traverse mode ambiguity</strong> on a remote — the single hardest UX call (D3); prototype on the <code>Orrery_TV</code> emulator early (S2) before committing the contract.</li><li><strong>Announcement volume</strong> — narrate on focus only, one datum; reuse ADR-025&#39;s &quot;don&#39;t flood&quot; lesson.</li><li><strong>Focus-position drift</strong> — mirror buttons must track object screen-projection as the camera moves; throttle to <code>requestAnimationFrame</code>, and only for the focused/near items (perf, per the 2026-06-19 render-storm lesson).</li><li><strong>Palette index size/cost</strong> — build the fuzzy index from existing manifests; lazy-load.</li></ul><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Every slice is additive + independently revertable: the primitive is new code; the mirror elevation enhances existing buttons (revert = the current click-only substrate); the TV layer is media-query-gated; the palette is a new component; the audit/statement are docs. No slice changes the rendering architecture (the point of the DOM-mirror approach).</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>ADR-025 (a11y Tier 1 + the Tier 2 deferral this executes) · ADR-056 (<code>window.__pickAt</code> project-to-client math, reused by the mirror) · RFC-030 + #375 (Google-TV target) · epic #149.</p><hr><p><em>Orrery · RFC-031 · Keyboard-first navigation, focus model &amp; WCAG 2.1 AA · July 2026</em></p>`,36)])])}const g=o(n,[["render",s]]);export{u as __pageData,g as default};
